Here’s the **simplest and cleanest code** to reverse a **Circular Linked List (CLL)** in C — no extra mess:  

```c
#include <stdio.h>
#include <stdlib.h>

struct Node {
    int data;
    struct Node* next;
};

// Create new node
struct Node* createNode(int value) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = value;
    newNode->next = NULL;
    return newNode;
}

// Insert at end (to create circular list)
struct Node* insertEnd(struct Node* head, int value) {
    struct Node* newNode = createNode(value);
    if (head == NULL) {
        newNode->next = newNode;
        return newNode;
    }
    struct Node* temp = head;
    while (temp->next != head)
        temp = temp->next;
    temp->next = newNode;
    newNode->next = head;
    return head;
}

// Display list
void display(struct Node* head) {
    if (head == NULL) return;
    struct Node* temp = head;
    do {
        printf("%d ", temp->data);
        temp = temp->next;
    } while (temp != head);
    printf("\n");
}

// Reverse circular linked list
struct Node* reverse(struct Node* head) {
    if (head == NULL || head->next == head)
        return head;

    struct Node *prev = NULL, *curr = head, *next = NULL;
    do {
        next = curr->next;
        curr->next = prev;
        prev = curr;
        curr = next;
    } while (curr != head);

    head->next = prev;  // old head points to new last node
    head = prev;        // new head
    return head;
}

int main() {
    struct Node* head = NULL;
    head = insertEnd(head, 10);
    head = insertEnd(head, 20);
    head = insertEnd(head, 30);
    head = insertEnd(head, 40);

    printf("Original CLL: ");
    display(head);

    head = reverse(head);

    printf("Reversed CLL: ");
    display(head);

    return 0;
}
```

✅ **How it works (simple logic):**  
- Use three pointers: `prev`, `curr`, and `next`.  
- Reverse links until you come back to the starting node.  
- Fix the head’s last pointer (`head->next = prev`) and update `head = prev`.  

